  ('manifestation', null, null, 'Today I move toward the life I am building, one intentional choice at a time.', null, null, null, null, null, null, 'peace', 'draft'),
  ('manifestation', null, null, 'I welcome opportunities that match my values, and I am prepared to act on them.', null, null, null, null, null, null, 'peace', 'draft'),
