  ('manifestation', null, null, 'I attract meaningful connections by being honest about who I am.', null, null, null, null, null, null, 'peace', 'draft'),
  ('manifestation', null, null, 'Clarity comes as I take the next small step, not before it.', null, null, null, null, null, null, 'peace', 'draft'),
