  ('affirmation', null, null, 'I can be kind and still have boundaries.', null, null, null, null, null, null, 'peace', 'draft'),
  ('affirmation', null, null, 'I do not have to be perfect to be valuable.', null, null, null, null, null, null, 'peace', 'draft'),
